package com.solarmind.service;
import com.solarmind.config.SolarProperties; import com.solarmind.entity.SolarPanel; import com.solarmind.exception.NoSuitablePanelException; import com.solarmind.repository.SolarPanelRepository; import org.springframework.stereotype.Service; import java.math.*; import java.util.*; import java.util.regex.*;
@Service public class RecommendationService { private final SolarPanelRepository panels; private final SolarProperties properties; private final GenerationEstimator generation; public RecommendationService(SolarPanelRepository panels,SolarProperties properties,GenerationEstimator generation){this.panels=panels;this.properties=properties;this.generation=generation;}
 public Result calculate(BigDecimal monthlyConsumption,BigDecimal monthlyBill,BigDecimal roofArea,String roofType,BigDecimal budget){BigDecimal annual=monthlyConsumption.multiply(BigDecimal.valueOf(12)); BigDecimal tariff=monthlyBill.divide(monthlyConsumption,8,RoundingMode.HALF_UP); BigDecimal required=annual.divide(properties.generationFactorKwhPerKwYear(),8,RoundingMode.HALF_UP); BigDecimal usable=roofArea.multiply(properties.roofTypeUsableFactor().getOrDefault(roofType,BigDecimal.ONE)); List<Candidate> valid=panels.findAll().stream().map(this::candidate).filter(Objects::nonNull).toList(); if(valid.isEmpty())throw new NoSuitablePanelException("No panel has valid wattage and dimensions"); Candidate selected=valid.stream().filter(p->p.area.multiply(properties.roofLayoutFactor()).compareTo(usable)<=0).sorted(Comparator.comparing((Candidate p)->p.panel.getEfficiency(),Comparator.nullsLast(Comparator.reverseOrder())).thenComparing(p->p.panel.getWattage(),Comparator.reverseOrder())).findFirst().orElse(valid.stream().min(Comparator.comparing(p->p.area)).orElseThrow()); int count=required.multiply(BigDecimal.valueOf(1000)).divide(BigDecimal.valueOf(selected.panel.getWattage()),0,RoundingMode.CEILING).intValueExact(); BigDecimal actual=BigDecimal.valueOf(count).multiply(BigDecimal.valueOf(selected.panel.getWattage())).divide(BigDecimal.valueOf(1000),8,RoundingMode.HALF_UP); BigDecimal annualGeneration=generation.estimate(actual); BigDecimal savings=annualGeneration.multiply(tariff).setScale(2,RoundingMode.HALF_UP); BigDecimal cost=actual.multiply(properties.installationCostPerKw()).setScale(2,RoundingMode.HALF_UP); BigDecimal payback=savings.signum()>0?cost.divide(savings,4,RoundingMode.HALF_UP):null; BigDecimal requiredRoof=selected.area.multiply(BigDecimal.valueOf(count)).multiply(properties.roofLayoutFactor()).setScale(2,RoundingMode.HALF_UP); boolean feasible=requiredRoof.compareTo(usable)<=0; boolean within=cost.compareTo(budget)<=0; BigDecimal co2=annualGeneration.multiply(properties.gridEmissionFactor()).setScale(2,RoundingMode.HALF_UP); return new Result(selected.panel,count,required.setScale(2,RoundingMode.HALF_UP),actual,annualGeneration,savings,cost,payback,co2,tariff,requiredRoof,feasible,within); }
 private Candidate candidate(SolarPanel p){try{if(p.getWattage()==null||p.getWattage()<=0||p.getDimensions()==null)return null; Matcher m=Pattern.compile("([0-9]+(?:\\.[0-9]+)?)").matcher(p.getDimensions()); List<BigDecimal> n=new ArrayList<>(); while(m.find()&&n.size()<2)n.add(new BigDecimal(m.group(1))); if(n.size()<2)return null; return new Candidate(p,n.get(0).multiply(n.get(1)).divide(BigDecimal.valueOf(1_000_000),8,RoundingMode.HALF_UP));}catch(RuntimeException e){return null;}}
 private record Candidate(SolarPanel panel,BigDecimal area){} public record Result(SolarPanel panel,int panelCount,BigDecimal requiredCapacity,BigDecimal actualCapacity,BigDecimal annualGeneration,BigDecimal annualSavings,BigDecimal estimatedCost,BigDecimal paybackYears,BigDecimal co2Reduction,BigDecimal effectiveTariff,BigDecimal requiredRoofArea,boolean roofFeasible,boolean withinBudget){}
}
